ALTER TABLE workflow_definitions ADD COLUMN code VARCHAR(64) NULL, ADD COLUMN description VARCHAR(1000), ADD UNIQUE KEY uk_workflow_code(code);
ALTER TABLE workflow_versions MODIFY status ENUM('DRAFT','VALIDATED','PUBLISHED','RETIRED') NOT NULL, ADD COLUMN layout_json JSON NULL, ADD COLUMN validated_hash BINARY(32), ADD COLUMN validated_by BINARY(16), ADD COLUMN validated_at TIMESTAMP(6), ADD COLUMN change_note VARCHAR(1000), ADD COLUMN created_by BINARY(16) NULL;
CREATE TABLE workflow_validations(id BINARY(16) PRIMARY KEY,workflow_version_id BINARY(16) NOT NULL,graph_hash BINARY(32) NOT NULL,validator_version VARCHAR(64) NOT NULL,status ENUM('PASSED','FAILED') NOT NULL,errors_json JSON NOT NULL,created_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),CONSTRAINT fk_validation_version FOREIGN KEY(workflow_version_id) REFERENCES workflow_versions(id),INDEX ix_validation_version(workflow_version_id,created_at)) ENGINE=InnoDB;
CREATE TABLE workflow_bindings(id BINARY(16) PRIMARY KEY,direction ENUM('PROD_TO_OFFICE','OFFICE_TO_PROD') NOT NULL,scope_type ENUM('GLOBAL','DEPARTMENT','GROUP','BUSINESS_SYSTEM') NOT NULL,scope_id BINARY(16),workflow_version_id BINARY(16) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_by BINARY(16) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),CONSTRAINT fk_binding_version FOREIGN KEY(workflow_version_id) REFERENCES workflow_versions(id),UNIQUE KEY uk_workflow_binding(direction,scope_type,scope_id)) ENGINE=InnoDB;
CREATE TABLE workflow_node_instances(id BINARY(16) PRIMARY KEY,instance_id BINARY(16) NOT NULL,node_id VARCHAR(64) NOT NULL,node_type ENUM('START','APPROVAL','CONDITION','NOTIFY','END_APPROVED') NOT NULL,status ENUM('WAITING','ACTIVE','APPROVED','REJECTED','SKIPPED','COMPLETED','BLOCKED') NOT NULL,assignee_mode ENUM('SINGLE','ANY','ALL'),resolver_snapshot JSON,candidate_snapshot JSON,required_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,approved_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,activated_at TIMESTAMP(6),due_at TIMESTAMP(6),completed_at TIMESTAMP(6),version BIGINT UNSIGNED NOT NULL DEFAULT 1,UNIQUE KEY uk_node_instance(instance_id,node_id),CONSTRAINT fk_node_workflow_instance FOREIGN KEY(instance_id) REFERENCES workflow_instances(id)) ENGINE=InnoDB;
CREATE TABLE approver_bindings(id BINARY(16) PRIMARY KEY,resolver_code VARCHAR(64) NOT NULL,scope_type ENUM('GLOBAL','DEPARTMENT','GROUP') NOT NULL,scope_id BINARY(16),user_id BINARY(16) NOT NULL,priority SMALLINT UNSIGNED NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE,CONSTRAINT fk_approver_user FOREIGN KEY(user_id) REFERENCES user_accounts(id),UNIQUE KEY uk_approver_binding(resolver_code,scope_type,scope_id,user_id)) ENGINE=InnoDB;
ALTER TABLE workflow_instances ADD COLUMN selected_path JSON NULL;
ALTER TABLE exchange_requests MODIFY status ENUM('DRAFT','CHECKING','SCANNING','SCAN_FAILED','IN_REVIEW','WORKFLOW_BLOCKED','REJECTED_CHECK','PENDING_APPROVAL','APPROVED','TRANSFER_PENDING','COPYING','READY','PARTIALLY_DELIVERED','DELIVERED','REJECTED','CANCELLED','EXPIRED','REVOKED','QUARANTINED','BLOCKED') NOT NULL;
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'workflow.manage' FROM roles WHERE code='SECURITY_ADMIN';
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'workflow.publish' FROM roles WHERE code='SECURITY_ADMIN';
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'approval.act' FROM roles WHERE code IN ('GROUP_MANAGER','DEPARTMENT_MANAGER','SECURITY_OFFICER');
INSERT IGNORE INTO role_permissions(role_id,permission) SELECT id,'approval.admin_on_behalf' FROM roles WHERE code='SECURITY_ADMIN';
